with base as (select *, round(humidity, 1) as humidity_rounded from device_readings where to_date(reading_ts) < '2024-05-01') select *, lag(humidity) over w_grp as prev_humidity, lead(pressure) over w_grp as next_pressure, lag(pressure) over w_grp as prev_pressure, row_number() over w_grp as row_seq from base where firmware = '1.0.3' window w_grp as (partition by device_code order by reading_ts, id)
